'use client'
/** Checkbox: the MATRIX card `ui-check` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-check')!

export type MatrixCheckProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixCheck(props: MatrixCheckProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
